@app.cell
def _(Path, hashlib, io, json, pd, spatial_lookup, urlopen):
    source_commit = "45d2a7a36c9f5e870b9ad0814b4517fe4d586969"
    source_base = f"https://raw.githubusercontent.com/joseph-xuan/si618-fall2026-project-team8/{source_commit}/"
    notebook_dir = Path(__file__).resolve().parent

    def read_source(relative):
        candidates = [notebook_dir / relative, notebook_dir.parent / relative, Path.cwd() / relative]
        found = next((p for p in candidates if p.is_file()), None)
        if found is not None:
            content = found.read_bytes()
        else:
            with urlopen(source_base + relative, timeout=180) as response:
                content = response.read()
        digest = hashlib.sha256(content).hexdigest()
        assert digest == spatial_lookup["sources"][relative], f"Changed source: {relative}"
        return content

    hd_raw = pd.read_csv(io.BytesIO(read_source("data/raw/ipeds_2019/hd2019.csv")),encoding="cp1252",low_memory=False)
    ef_raw = pd.read_csv(io.BytesIO(read_source("data/raw/ipeds_2019/ef2019a_rv.csv")),encoding="cp1252",low_memory=False)
    vehicles_raw = pd.read_parquet(io.BytesIO(read_source("data/processed/vehicles_us_2019_sample.parquet")))
    sample_metadata = json.loads(read_source("outputs/automotive_sample_metadata.json"))
    input_shapes = pd.DataFrame([
        ["IPEDS HD2019",*hd_raw.shape,"institution"],
        ["IPEDS EF2019A revised",*ef_raw.shape,"enrollment reporting level"],
        ["Automotive fixed sample",*vehicles_raw.shape,"unique listing record"],
    ],columns=["source","rows","columns","meaning_of_row"])
    input_shapes
    return ef_raw, hd_raw, sample_metadata, vehicles_raw


@app.cell
def _(ef_raw, hd_raw, mo, vehicles_raw):
    mo.vstack([
        mo.md("**Inspect the inputs before cleaning**"),
        hd_raw[["UNITID","INSTNM","STABBR","COUNTYCD","LATITUDE","LONGITUD"]].head(),
        ef_raw[["UNITID","EFALEVEL","EFTOTLT","EFNRALT"]].head(),
        vehicles_raw[["listing_key","latitude","longitude","make_model_raw","body_style_raw","model_year"]].head(),
    ])
    return


@app.cell
def _(ef_raw, hd_raw, np, pd):
    states = 'AL AK AZ AR CA CO CT DE DC FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY'.split()
    hd = hd_raw.rename(columns=lambda name: name.strip()).copy()
    hd = hd.assign(INSTNM=hd['INSTNM'].astype('string').str.strip(), STABBR=hd['STABBR'].astype('string').str.strip(), ACT=hd['ACT'].astype('string').str.strip(), LATITUDE=pd.to_numeric(hd['LATITUDE'], errors='coerce'), LONGITUD=pd.to_numeric(hd['LONGITUD'], errors='coerce'))
    institution_steps = [['HD2019 loaded', len(hd)]]
    hd_us = hd[hd['STABBR'].isin(states)]
    institution_steps.append(['50 states and DC', len(hd_us)])
    hd_active = hd_us[hd_us['ACT'].isin(['A', 'N', 'R'])]
    institution_steps.append(['Active, new, or restored', len(hd_active)])
    hd_four_year = hd_active[(hd_active['ICLEVEL'] == 1) & (hd_active['DEGGRANT'] == 1)]
    institution_steps.append(['Four-year and degree-granting', len(hd_four_year)])
    hd_clean = hd_four_year[hd_four_year['LATITUDE'].between(-90, 90) & hd_four_year['LONGITUD'].between(-180, 180) & ~((hd_four_year['LATITUDE'] == 0) & (hd_four_year['LONGITUD'] == 0))]
    institution_steps.append(['Usable coordinates', len(hd_clean)])
    institutions = hd_clean[['UNITID', 'INSTNM', 'STABBR', 'LATITUDE', 'LONGITUD']].rename(columns={'UNITID': 'unitid', 'INSTNM': 'institution_name', 'STABBR': 'state', 'LATITUDE': 'campus_latitude', 'LONGITUD': 'campus_longitude'})
    ef = ef_raw.rename(columns=lambda name: name.strip()).copy()
    ef_levels = ef[ef['EFALEVEL'].isin([1, 2, 12])][['UNITID', 'EFALEVEL', 'EFTOTLT', 'EFNRALT']].copy()
    ef_levels['EFTOTLT'] = pd.to_numeric(ef_levels['EFTOTLT'], errors='coerce')
    ef_levels['EFNRALT'] = pd.to_numeric(ef_levels['EFNRALT'], errors='coerce')
    ef_levels.loc[ef_levels['EFTOTLT'] < 0, 'EFTOTLT'] = np.nan
    ef_levels.loc[ef_levels['EFNRALT'] < 0, 'EFNRALT'] = np.nan
    enrollment = ef_levels.pivot_table(index='UNITID', columns='EFALEVEL', values='EFTOTLT', aggfunc='first', dropna=False).rename(columns={1: 'total_students', 2: 'undergraduate_students', 12: 'graduate_students_reported'}).reset_index()
    international = ef_levels[ef_levels['EFALEVEL'] == 1][['UNITID', 'EFNRALT']].rename(columns={'EFNRALT': 'international_students'})
    enrollment = pd.merge(enrollment, international, on='UNITID', how='left')
    enrollment = enrollment.rename(columns={'UNITID': 'unitid'})
    enrollment = enrollment.assign(graduate_zero_inferred=enrollment['graduate_students_reported'].isna() & enrollment['total_students'].gt(0) & enrollment['undergraduate_students'].eq(enrollment['total_students']))
    enrollment['graduate_students'] = np.where(enrollment['graduate_zero_inferred'], 0, enrollment['graduate_students_reported'])
    enrollment['international_student_share'] = enrollment['international_students'] / enrollment['total_students']
    enrollment['graduate_student_share'] = enrollment['graduate_students'] / enrollment['total_students']
    enrollment['graduate_share_reported_only'] = enrollment['graduate_students_reported'] / enrollment['total_students']
    for _column in ['international_student_share', 'graduate_student_share', 'graduate_share_reported_only']:
        enrollment.loc[~enrollment[_column].between(0, 1), _column] = np.nan
    campuses = pd.merge(institutions, enrollment, on='unitid', how='left', indicator=True)
    enrollment_audit = pd.DataFrame([['EF2019A rows loaded', len(ef)], ['Keep EFALEVEL 1, 2, 12', len(ef_levels)], ['Reshape to one row per institution', len(enrollment)], ['Selected institutions matched to enrollment', int((campuses['_merge'] == 'both').sum())], ['Selected institutions without enrollment (kept)', int((campuses['_merge'] == 'left_only').sum())], ['Enrollment institutions outside the selection (not used)', int((~enrollment['unitid'].isin(institutions['unitid'])).sum())]], columns=['stage', 'rows'])
    campuses = campuses.drop(columns='_merge')
    institution_audit = pd.DataFrame(institution_steps, columns=['stage', 'rows'])
    institution_audit['removed_since_previous'] = -institution_audit['rows'].diff()
    return (campuses,)


@app.cell
def _(pd, re, sample_metadata, vehicles_raw):
    vehicles_check = vehicles_raw[vehicles_raw['country'] == 'US'].copy()
    _date_text = vehicles_check['date_posted'].astype('string').str.replace('[+-]\\d{2}:?\\d{2}$|Z$', '', regex=True)
    vehicles_check['posting_year'] = pd.to_datetime(_date_text, errors='coerce').dt.year
    vehicles_check = vehicles_check[vehicles_check['posting_year'] == 2019]
    vehicles_check['latitude'] = pd.to_numeric(vehicles_check['latitude'], errors='coerce')
    vehicles_check['longitude'] = pd.to_numeric(vehicles_check['longitude'], errors='coerce')
    vehicles_check = vehicles_check[vehicles_check['latitude'].between(-90, 90) & vehicles_check['longitude'].between(-180, 180) & ~((vehicles_check['latitude'] == 0) & (vehicles_check['longitude'] == 0)) & vehicles_check['listing_key'].notna() & vehicles_check['listing_key'].ne('')].drop_duplicates('listing_key')
    brand_aliases = {brand: list(aliases) for brand, aliases in sample_metadata['brand_aliases'].items()}
    brand_aliases.update({'hummer': ['hummer'], 'freightliner': ['freightliner'], 'peterbilt': ['peterbilt'], 'kenworth': ['kenworth']})
    alias_to_brand = {alias: brand for brand, aliases in brand_aliases.items() for alias in aliases}
    brand_pattern = '^(' + '|'.join((re.escape(alias) for alias in sorted(alias_to_brand, key=len, reverse=True))) + ')\\b'
    make_model = vehicles_check['make_model_raw'].fillna('').str.lower().str.replace('[^a-z0-9]+', ' ', regex=True).str.strip().str.replace('^(?:19|20)\\d{2}\\s+', '', regex=True)
    manufacturer = make_model.str.extract(brand_pattern, expand=False).map(alias_to_brand)
    body_mapping = dict(sample_metadata['body_style_mapping'])
    body_mapping.update({'sport utility': 'suv', '4d sport utility': 'suv', 'crew cab pickup': 'pickup', 'pickup truck': 'pickup', 'extended cab pickup': 'pickup', 'standard cab pickup': 'pickup', 'regular cab pickup': 'pickup', 'mini van passenger': 'minivan', 'full size cargo van': 'van'})
    body_text = vehicles_check['body_style_raw'].fillna('').str.lower().str.replace('[^a-z0-9]+', ' ', regex=True).str.strip()
    body_style = body_text.map(body_mapping)
    model_year = pd.to_numeric(vehicles_check['model_year'], errors='coerce')
    valid_year = model_year.between(1886, vehicles_check['posting_year'] + 1)
    model_year = model_year.where(valid_year)
    vehicle_age = vehicles_check['posting_year'] - model_year
    vehicle_age = vehicle_age.where(model_year <= vehicles_check['posting_year'])
    japanese_brands = set(sample_metadata['japanese_brand_list'])
    is_japanese = manufacturer.isin(japanese_brands).astype('boolean')
    is_japanese = is_japanese.mask(manufacturer.isna())
    vehicles = vehicles_check.assign(manufacturer=manufacturer, body_style=body_style, model_year=model_year, vehicle_age=vehicle_age, is_japanese_brand=is_japanese).reset_index(drop=True)
    vehicle_audit = pd.DataFrame([['Sample loaded', len(vehicles_raw)], ['US, 2019, valid coordinates and identity', len(vehicles_check)], ['Unique listing keys after cleaning', vehicles['listing_key'].nunique()]], columns=['stage', 'rows'])
    vehicle_missing = vehicles[['manufacturer', 'body_style', 'vehicle_age']].isna().sum().rename('missing_rows').reset_index().rename(columns={'index': 'variable'})
    vehicle_missing['missing_percent'] = 100 * vehicle_missing['missing_rows'] / len(vehicles)
    return (vehicles,)


@app.cell
def _(base64, io, np, pd, spatial_lookup, vehicles_raw, zlib):
    county_geo = pd.read_csv(io.BytesIO(zlib.decompress(base64.b85decode(spatial_lookup["county_csv"]))),
        dtype={"county_id":"string","state_fips":"string","cbsa_code":"string","region_id":"string"})
    assignment_codes = np.frombuffer(zlib.decompress(base64.b85decode(spatial_lookup["county_codes"])),dtype="<i2")
    assert len(assignment_codes) == len(vehicles_raw)
    _assigned_names = county_geo["county_id"].to_numpy()[np.maximum(assignment_codes,0)].astype(object)
    _assigned_names[assignment_codes<0] = None
    listing_lookup = pd.DataFrame({"listing_key":vehicles_raw["listing_key"],"county_id":_assigned_names})
    assert listing_lookup["listing_key"].is_unique and county_geo["county_id"].is_unique
    county_geo.head()
    return county_geo, listing_lookup


@app.cell
def _(campuses, county_geo, hd_raw, listing_lookup, pd, vehicles):
    _school_counties = hd_raw[["UNITID","COUNTYCD"]].rename(columns={"UNITID":"unitid"}).copy()
    _school_counties["county_id"] = pd.to_numeric(_school_counties["COUNTYCD"],errors="coerce").astype("Int64").astype("string").str.zfill(5)
    college_regions = pd.merge(campuses,_school_counties[["unitid","county_id"]],on="unitid",how="left",validate="one_to_one")
    college_regions = pd.merge(college_regions,county_geo,on="county_id",how="inner",validate="many_to_one")
    vehicle_regions = pd.merge(vehicles,listing_lookup,on="listing_key",how="left",validate="one_to_one")
    vehicle_regions = pd.merge(vehicle_regions,county_geo[["county_id","region_id"]],on="county_id",how="inner",validate="many_to_one")
    assert college_regions["unitid"].is_unique and vehicle_regions["listing_key"].is_unique
    merge_audit = pd.DataFrame([
        ["Universities",len(campuses),len(college_regions),len(campuses)-len(college_regions)],
        ["Listings",len(vehicles),len(vehicle_regions),len(vehicles)-len(vehicle_regions)],
    ],columns=["records","before_geographic_scope","retained","outside_scope_or_unmatched"])
    merge_audit
    return college_regions, vehicle_regions


@app.cell(hide_code=True)
def _(college_regions, mo, spatial_audit, vehicle_regions, vehicles):
    mo.md(f"""
    **Merge interpretation.** We retain {len(college_regions):,} universities and
    {len(vehicle_regions):,} unique listings. Of the {len(vehicles)-len(vehicle_regions):,}
    excluded listings, the lookup audit records
    {sum(spatial_audit['unmatched_vehicle_reported_states'].get(s,0) for s in ['AK','HI']):,}
    with reported state AK/HI and
    {len(vehicles)-len(vehicle_regions)-sum(spatial_audit['unmatched_vehicle_reported_states'].get(s,0) for s in ['AK','HI']):,}
    with another or missing state. Reported state and coordinates can disagree. The
    geographic lookup has {spatial_audit['vehicles_boundary_ties_unique_points']} boundary-tie
    coordinates; this assignment uncertainty is retained as a limitation.

    ### Regional aggregation

    The following reusable function performs the same pandas grouping for both partitions.
    It counts universities, pools enrollment denominators, recomputes listing proportions
    and summarizes within-area age distributions. Regions without usable listings have
    zero counts and missing proportions.
    """)
    return


@app.cell
def _(college_regions, county_geo, np, pd, vehicle_regions):
    def build_area(schools, listings, geography, key):
        school_rows = []
        for area_id, group in schools.groupby(key,observed=True):
            total = pd.to_numeric(group["total_students"],errors="coerce")
            known = total.gt(0) & np.isfinite(total)
            known_total = total.where(known).sum()
            row = {"area_id":area_id,"n_colleges":len(group),"total_students":known_total,
                "enrollment_coverage":known.mean(),
                "state":group["state"].value_counts().sort_index().idxmax()}
            for kind in ["international","graduate"]:
                valid = known & group[kind+"_student_share"].notna()
                denominator = total.where(valid).sum()
                row[kind+"_student_share"] = (group.loc[valid,kind+"_student_share"]*total[valid]).sum()/denominator if denominator>0 else np.nan
                row[kind+"_coverage"] = denominator/known_total if known_total>0 else np.nan
            school_rows.append(row)
        school_stats = pd.DataFrame(school_rows).set_index("area_id")
        area_geo = geography.groupby(key,observed=True).agg(
            land_sqmi=("land_sqmi","sum"),population=("POPESTIMATE2019","sum"),
            n_counties=("county_id","size"),n_states=("state_fips","nunique"))
        listing_stats = listings.groupby(key,observed=True).agg(
            n_listings=("listing_key","size"),n_known_brand=("manufacturer","count"),
            n_known_body=("body_style","count"),n_known_age=("vehicle_age","count"),
            japanese_share=("is_japanese_brand","mean"))
        age_stats = listings.groupby(key,observed=True)["vehicle_age"].quantile([.1,.25,.5,.75,.9]).unstack()
        age_stats.columns = ["age_q10","age_q25","age_median","age_q75","age_q90"]
        age_stats["age_iqr"] = age_stats["age_q75"]-age_stats["age_q25"]
        result = school_stats.join(area_geo).join(listing_stats).join(age_stats)
        for column in ["n_listings","n_known_brand","n_known_body","n_known_age"]:
            result[column] = result[column].fillna(0).astype(int)
        for column,prefix in [("manufacturer","brand_"),("body_style","body_")]:
            counts = pd.crosstab(listings[key],listings[column])
            shares = counts.div(counts.sum(axis=1).replace(0,np.nan),axis=0).add_prefix(prefix)
            result = result.join(shares)
        result = result.assign(
            college_density=result["n_colleges"]/result["land_sqmi"],
            population_density=result["population"]/result["land_sqmi"],
            international_10pp=result["international_student_share"]/.1,
            graduate_10pp=result["graduate_student_share"]/.1)
        result["log2_college_density"] = np.log2(result["college_density"])
        result["log2_population_density"] = np.log2(result["population_density"])
        result["log_students"] = np.log(result["total_students"].where(result["total_students"]>0))
        if key=="county_id":
            result["cluster_id"] = geography.set_index("county_id")["region_id"].reindex(result.index)
        else:
            result["cluster_id"] = result.index
        return result.reset_index()

    county = build_area(college_regions,vehicle_regions,county_geo,"county_id")
    cbsa = build_area(college_regions,vehicle_regions,county_geo,"region_id")
    _same_listings = vehicle_regions[vehicle_regions["county_id"].isin(college_regions["county_id"].unique())]
    cbsa_same = build_area(college_regions,_same_listings,county_geo,"region_id")
    cbsa_only = cbsa[cbsa["area_id"].str.startswith("CBSA_")].copy()
    area_tables = {"County":county,"CBSA + outside counties":cbsa,
        "CBSA, same listing support":cbsa_same,"CBSA only":cbsa_only}
    county.head()
    return area_tables, cbsa, cbsa_same, county


@app.cell
def _(area_tables, cbsa_same, county, np, pd):
    _checks = []
    for _scale,_areas in area_tables.items():
        assert _areas["area_id"].is_unique
        for _prefix,_known in [("brand_","n_known_brand"),("body_","n_known_body")]:
            _columns = [c for c in _areas.columns if c.startswith(_prefix)]
            _usable = _areas[_areas[_known]>0]
            assert np.allclose(_usable[_columns].sum(axis=1),1)
        _checks.append([_scale,len(_areas),int(_areas["n_listings"].sum()),
            int((_areas["n_known_brand"]>=100).sum()),int((_areas["n_known_body"]>=100).sum()),
            int((_areas["n_known_age"]>=100).sum())])
    assert int(county["n_listings"].sum()) == int(cbsa_same["n_listings"].sum())
    coverage_table = pd.DataFrame(_checks,columns=["partition","areas_with_universities","unique_listings",
        "areas_100_known_brand","areas_100_known_body","areas_100_known_age"])
    coverage_table
    return


@app.cell
def _(county, mo, vehicle_regions):
    _missing = vehicle_regions[["manufacturer","body_style","vehicle_age"]].isna().mean().mul(100)
    missing_table = _missing.rename("missing_percent").reset_index().rename(columns={"index":"attribute"})
    _description = county[["international_student_share","graduate_student_share","college_density","population_density"]].describe().T
    mo.vstack([mo.md("**Missing attributes (%) and county predictor distributions**"),missing_table.round(2),_description.round(3)])
    return (missing_table,)


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### Shared analysis rules

    We use multiple linear regression because the predictors and area-level outcomes are
    numeric and the questions require adjustment for location. Every area receives equal
    weight; this estimates associations across qualifying areas, not across all listings.
    Shares are expressed in percentage points. A student-share coefficient is for a
    10-percentage-point increase; a log2 university-density coefficient is for a doubling.

    All specifications for one outcome use the same qualifying rows. For state controls,
    states with only one qualifying region are excluded to avoid exact-fit leverage points.
    For a cross-state CBSA we use its most represented university state, a simplification;
    we also check regions whose entire geographic extent lies in one state.

    **Assumptions and response.** We inspect residuals versus fitted values, normal-quantile
    plots, skewness, leverage and influence. Linear regression summarizes an average linear
    association and need not describe every part of a distribution. OLS shares are not
    restricted to 0–100, so we count out-of-range fitted shares. HC3 standard errors allow
    unequal residual variance and use a large-sample normal approximation; they do not
    solve spatial dependence. County cluster estimates additionally allow counties within
    the same CBSA to be correlated, using a t reference with the number of clusters minus
    one degrees of freedom. Dependence between those clusters could still make p-values
    too optimistic. We do not claim non-overlapping areas are independent.

    The helper functions below apply the same rules across outcomes. The regression is the
    course's multiple linear regression; robust covariance and BH adjustment are explicit
    extensions for unequal variance, shared regions and multiple comparisons. They do not
    turn this observational study into a causal design.
    """)
    return


@app.cell
def _(mo, multipletests, np, pd, plt, smf, stats):
    def sample_rows(table,question,outcome,threshold=100):
        known = "n_known_age" if outcome.startswith("age_") else ("n_known_body" if outcome.startswith("body_") else "n_known_brand")
        keep = table["total_students"].gt(0) & table["enrollment_coverage"].ge(.9) & table[known].ge(threshold)
        if question in [1,2]:
            kind = "international" if question==1 else "graduate"
            keep &= table[kind+"_coverage"].ge(.9)
        selected = table[keep].dropna(subset=[outcome,"log_students","log2_college_density","log2_population_density"]).copy()
        state_counts = selected["state"].value_counts()
        return selected[selected["state"].map(state_counts)>1].copy()

    def fit_region(selected,question,outcome,spec="full",covariance="HC3"):
        exposure = {1:"international_10pp",2:"graduate_10pp",3:"log2_college_density"}[question]
        use = selected.copy()
        if spec!="unadjusted":
            counts = use["state"].value_counts()
            use = use[use["state"].map(counts)>1].copy()
        use["state"] = pd.Categorical(use["state"].astype(str))
        use["value"] = use[outcome].astype(float) * (1 if outcome.startswith("age_") else 100)
        terms = [exposure]
        if spec!="unadjusted":
            terms.append("C(state)")
        if spec in ["population","full"]:
            terms.append("log2_population_density")
        if spec=="full":
            terms.append("log_students")
            if question!=3:
                terms.append("log2_college_density")
        ordinary = smf.ols("value ~ "+" + ".join(terms),data=use).fit()
        assert np.linalg.matrix_rank(ordinary.model.exog) == ordinary.model.exog.shape[1]
        if covariance=="CBSA cluster":
            robust = ordinary.get_robustcov_results(cov_type="cluster",groups=use["cluster_id"].to_numpy(),
                use_correction=True,df_correction=True,use_t=True)
        else:
            robust = ordinary.get_robustcov_results(cov_type="HC3",use_t=False)
        position = ordinary.model.exog_names.index(exposure)
        low,high = robust.conf_int()[position]
        row = {"question":question,"outcome":outcome,"spec":spec,"covariance":covariance,
            "n":len(use),"clusters":use["cluster_id"].nunique(),"coefficient":float(robust.params[position]),
            "ci_low":float(low),"ci_high":float(high),"statistic":float(robust.tvalues[position]),
            "p":float(robust.pvalues[position]),"reference":"t (cluster df)" if covariance=="CBSA cluster" else "z (HC3)"}
        return {"ordinary":ordinary,"robust":robust,"data":use,"question":question,"outcome":outcome,"exposure":exposure},row

    def run_models(tables,question,outcomes,threshold=100,specs=None):
        if specs is None:
            specs = ["unadjusted","state","population","full"]
        records,models = [],{}
        for scale,table in tables.items():
            for outcome in outcomes:
                selected = sample_rows(table,question,outcome,threshold)
                for spec in specs:
                    model,row = fit_region(selected,question,outcome,spec)
                    records.append({"partition":scale,"threshold":threshold,**row})
                    if spec=="full":
                        models[(scale,outcome)] = model
                if scale=="County" and "full" in specs:
                    _,row = fit_region(selected,question,outcome,"full","CBSA cluster")
                    records.append({"partition":scale,"threshold":threshold,**row})
        results = pd.DataFrame(records)
        results["q"] = np.nan
        for _,family in results.groupby(["partition","spec","covariance","threshold"],observed=True):
            results.loc[family.index,"q"] = multipletests(family["p"],method="fdr_bh")[1]
        return results,models

    def pick(results,partition,outcome,spec="full",covariance="HC3"):
        row = results[(results["partition"]==partition)&(results["outcome"]==outcome)&
            (results["spec"]==spec)&(results["covariance"]==covariance)]
        assert len(row)==1
        return row.iloc[0]

    def result_table(results,columns):
        shown = results[columns].copy().round(4)
        for column in ["p","q"]:
            if column in shown:
                shown[column] = results[column].map(lambda value: f"{value:.3g}")
        return mo.ui.table(shown,page_size=max(len(shown),1),pagination=False,show_download=True)

    def quartiles(values):
        bins = pd.qcut(values,q=4,duplicates="drop")
        return bins.cat.rename_categories(["G"+str(i+1) for i in range(len(bins.cat.categories))])

    def diagnose(bundle):
        model = bundle["ordinary"]
        influence = model.get_influence()
        cook = influence.cooks_distance[0]
        omitted = bundle["data"].iloc[int(np.nanargmax(cook))]["area_id"]
        reduced = bundle["data"][bundle["data"]["area_id"]!=omitted]
        _,alternative = fit_region(reduced,bundle["question"],bundle["outcome"])
        predicted = model.fittedvalues
        return {"n":int(model.nobs),"residual_skew":float(stats.skew(model.resid)),
            "max_leverage":float(influence.hat_matrix_diag.max()),
            "cooks_above_4_over_n":int((cook>4/model.nobs).sum()),
            "fitted_outside_0_100":None if bundle["outcome"].startswith("age_") else int(((predicted<0)|(predicted>100)).sum()),
            "omitted_area":omitted,"coefficient_omit_most_influential":alternative["coefficient"]}

    def residual_plot(bundles,titles):
        fig,axes = plt.subplots(len(bundles),2,figsize=(10.5,3.4*len(bundles)),squeeze=False,layout="constrained")
        for row,(bundle,title) in enumerate(zip(bundles,titles)):
            model = bundle["ordinary"]
            axes[row,0].scatter(model.fittedvalues,model.resid,s=13,alpha=.45)
            axes[row,0].axhline(0,color="gray",ls="--",lw=1)
            axes[row,0].set(title=title+": residuals",xlabel="Fitted outcome",ylabel="Residual")
            stats.probplot(model.resid,dist="norm",plot=axes[row,1])
            axes[row,1].set(title=title+": normal-quantile check",xlabel="Normal quantile",ylabel="Ordered residual")
        return fig

    def coefficient_plot(results,outcomes,title):
        fig,ax = plt.subplots(figsize=(10.5,max(5,len(outcomes)*.55)),layout="constrained")
        for offset,scale,color in [(-.13,"County","#21688f"),(.13,"CBSA + outside counties","#b96a3c")]:
            use = results[(results["partition"]==scale)&(results["spec"]=="full")&(results["covariance"]=="HC3")].set_index("outcome").loc[outcomes]
            ax.errorbar(use["coefficient"],np.arange(len(outcomes))+offset,
                xerr=[use["coefficient"]-use["ci_low"],use["ci_high"]-use["coefficient"]],fmt="o",capsize=3,label=scale,color=color)
        ax.axvline(0,color="gray",lw=1,ls="--")
        ax.set_yticks(np.arange(len(outcomes)),[s.removeprefix("brand_").removeprefix("body_").replace("_"," ").title() for s in outcomes])
        ax.set(title=title,xlabel="Adjusted difference (percentage points); 95% HC3 intervals")
        ax.invert_yaxis()
        ax.legend(loc="best",fontsize=9)
        return fig

    return (
        coefficient_plot,
        diagnose,
        fit_region,
        pick,
        quartiles,
        residual_plot,
        result_table,
        run_models,
        sample_rows,
    )


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ---

    ## Question 1: Do areas with higher international student shares across their universities have different brand compositions in local used-car listings?

    ### Approach

    We first compare county brand compositions across international-share quartiles. We then
    regress each of the ten most common known brands' area shares on international share.
    The ten brands are selected by listing frequency before examining associations; all
    ten results are reported. Separate coefficients describe brand-specific associations,
    not an omnibus test of the entire composition. Brand shares sum to one and are related.

    The adjusted model includes state, log2 population density, log student enrollment and
    log2 university density. BH adjusts the ten p-values within each partition/specification;
    unadjusted and adjusted models are not pooled into one family. This is exploratory and
    does not correct for every specification considered during the project.
    """)
    return


@app.cell
def _(
    area_tables,
    county,
    diagnose,
    mo,
    pd,
    run_models,
    sample_rows,
    vehicle_regions,
):
    top_brands = vehicle_regions["manufacturer"].value_counts().head(10).index.tolist()
    brand_outcomes = ["brand_"+b for b in top_brands]
    rq1_results,rq1_models = run_models(area_tables,1,brand_outcomes)
    rq1_county = sample_rows(county,1,"brand_ford")
    rq1_diagnostics = pd.DataFrame([{"partition":s,**diagnose(rq1_models[(s,"brand_ford")])}
        for s in ["County","CBSA + outside counties"]])
    mo.vstack([mo.md("**Assumption and influence checks: Ford, the most common brand**"),rq1_diagnostics.round(3),
        mo.md("**Inspect the county sample**"),rq1_county[["area_id","international_student_share","brand_ford","population_density"]].head()])
    return brand_outcomes, rq1_county, rq1_diagnostics, rq1_models, rq1_results


