@app.cell
def _(
    brand_outcomes,
    cbsa,
    county,
    fit_region,
    mo,
    pd,
    result_table,
    rq1_results,
    rq2_outcomes,
    rq2_results,
    rq3_results,
    run_models,
    sample_rows,
):
    sensitivity_rows = []
    for _threshold in [50,100,200]:
        for _question,_outcomes,_focus in [(1,brand_outcomes,"brand_ford"),(2,rq2_outcomes,"age_median"),(3,["japanese_share"],"japanese_share")]:
            _results,_ = run_models({"County":county,"CBSA + outside counties":cbsa},_question,_outcomes,_threshold,specs=["full"])
            _focus_rows = _results[(_results["outcome"]==_focus)&(_results["covariance"]=="HC3")]
            sensitivity_rows.append(_focus_rows)
    sensitivity = pd.concat(sensitivity_rows,ignore_index=True)
    single_state_rows = []
    for _scale,_table in [("County",county),("CBSA + outside counties",cbsa)]:
        _single = _table[_table["n_states"]==1]
        _selected = sample_rows(_single,3,"japanese_share")
        _,_row = fit_region(_selected,3,"japanese_share")
        single_state_rows.append({"partition":_scale,**_row})
    single_state = pd.DataFrame(single_state_rows)
    cluster_results = pd.concat([rq1_results,rq2_results,rq3_results],ignore_index=True)
    cluster_results = cluster_results[(cluster_results["covariance"]=="CBSA cluster")&
        cluster_results["outcome"].isin(["brand_ford","brand_toyota","body_suv","age_median","japanese_share"])]
    mo.vstack([mo.md("**Threshold sensitivity: full adjustment**"),
        result_table(sensitivity,["question","partition","threshold","outcome","n","coefficient","ci_low","ci_high","p","q"]),
        mo.md("**County inference allowing within-CBSA dependence**"),
        result_table(cluster_results,["outcome","n","clusters","coefficient","ci_low","ci_high","statistic","p","q"]),
        mo.md("**RQ3: geographic extent restricted to one state**"),
        single_state[["partition","n","coefficient","ci_low","ci_high","p"]].round(4)])
    return


@app.cell
def _(area_tables, mo, pd, pick, rq3_results):
    support_checks = pd.DataFrame([
        {"comparison":s,"n":int(pick(rq3_results,s,"japanese_share")["n"]),
         "coefficient":pick(rq3_results,s,"japanese_share")["coefficient"],
         "ci_low":pick(rq3_results,s,"japanese_share")["ci_low"],
         "ci_high":pick(rq3_results,s,"japanese_share")["ci_high"],
         "p":pick(rq3_results,s,"japanese_share")["p"]}
        for s in area_tables])
    mo.vstack([mo.md("**RQ3: same listing support and pure-CBSA checks**"),support_checks.round(4)])
    return


